insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Asistente de Gerencia General y Financiera', 'Brinda asistencia a la Gerencia General y Financiera, en la gestión administrativa, comercial y de importaciones de Accesorios Ilimitados y de las empresas de Grupo IMISA, administrando documentación, pagos, facturación, contratos, proveedores, servicios, comunicaciones y procesos de importación, para dar seguimiento a los requerimientos y contribuir a la continuidad de las operaciones.', 'Graduado de nivel diversificado en Perito Contador, Secretaria bilingüe, Perito en Administración o carrera afín. 2 años en puesto similar. Capacidad de análisis, planificación, organización, priorización, negociación, seguimiento, comunicación efectiva, resolución de problemas, manejo de información confidencial.', 'ACCISA-006', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Licda. Miriam de Ríos', 'Administrativo', 'Q5,500.00 Base + Bonificación', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Gestión Documental de Importaciones", "funcion": "Gestión completa de importaciones, elaborar, procesar, organizar y controlar la documentación de importaciones aéreas, marítimas y terrestres de ACCISA, ISSA e IMISA, incluyendo conocimientos de embarque, facturas comerciales, listas de empaque y carta de traducción cuando corresponda.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Documental de Importaciones", "funcion": "Revisar documentos comerciales y de soporte, prepólizas, seguros, cartas porte, BL y demás documentos requeridos, y verificar el cumplimiento de regulaciones aduaneras con apoyo del agente aduanal.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Documental, Legal y de Seguros", "funcion": "Manejar y actualizar documentos legales de IMISA, ISSA, ACCISA e IERSA; renovar pólizas de seguros de vehículos del Grupo IMISA y gestionar el pago de impuestos de circulación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Documental, Legal y de Seguros", "funcion": "Gestionar trámites de traspaso de vehículos y la finalización de contratos de ARREND, siguiendo las instrucciones y documentos requeridos para el traspaso.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Emitir facturación de IERSA por arrendamiento y servicios.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Emitir y enviar estados de cuenta de clientes del Grupo IMISA.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Coordinar pagos de tarjetas de crédito del Sr. César Ríos y otros pagos solicitados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Imprimir y dar seguimiento a facturas de TIGO y CLARO, trasladarlas para pago y controlar facturas de ARREND, Acceso Digital, TSP, Cash Logistic, Barrascout, ANCARSA, LEOS, Click Logistic y otros proveedores.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Controlar pagos de Casa Ensenada y Escuintla y gestionar el requerimiento trimestral de pago de IUSI de edificios del Grupo IMISA y del Sr. César Ríos, incluyendo IUSI Escuintla.", "frecuencia": "", "tiempo": ""}, {"categoria": "Apoyo Contable y Financiero", "funcion": "Preparar mensualmente la documentación contable del Sr. César Ríos e importaciones para Contabilidad y trasladarla a la Licda. Miriam de Ríos para revisión.", "frecuencia": "", "tiempo": ""}, {"categoria": "Apoyo Contable y Financiero", "funcion": "Actualizar datos de cuentas bancarias empresariales en dólares y quetzales, enviar transferencias al exterior y cubrir el área de Asistente Financiera cuando sea requerido.", "frecuencia": "", "tiempo": ""}, {"categoria": "Mantenimientos, Telecomunicaciones y Suscripciones", "funcion": "Gestionar la compra de cojinetes para IMISA zona 4, solicitando autorización y el pedido correspondiente con el proveedor.", "frecuencia": "", "tiempo": ""}, {"categoria": "Mantenimientos, Telecomunicaciones y Suscripciones", "funcion": "Controlar mantenimientos de filtros, purificador de agua, elevador, cámaras, aire acondicionado, impresoras y EGSSA, y trasladar las facturas a contabilidad para pago.", "frecuencia": "", "tiempo": ""}, {"categoria": "Mantenimientos, Telecomunicaciones y Suscripciones", "funcion": "Gestionar renovaciones, cancelaciones o adquisiciones de dispositivos y planes TIGO para ACCISA e ISSA y renovar la suscripción de Prensa Libre del Sr. César Ríos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Asistencia a Gerencia, Ventas y Recepción", "funcion": "Cubrir el área de recepción durante una hora, apoyar la planta telefónica y asistir a ventas con cotizaciones para agencias y clientes, cartas y seguimiento de productos de importación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Asistencia a Gerencia, Ventas y Recepción", "funcion": "Administrar los correos electrónicos de ACCISA, IMISA, IERSA e ISSA y brindar asistencia directa a Gerencia General en las actividades administrativas y operativas solicitadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Mantener contacto con proveedores internacionales, agentes de carga, navieras, SAT, agentes aduanales, transportistas, agentes de seguridad y demás partes involucradas para dar fluidez al proceso.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Negociar y coordinar transportistas y almacenes fiscales para liberaciones y traslado de mercancía de puerto a bodega, cuidando costos y tiempos; coordinar con bodega la salida y descarga de pedidos completos de ISSA cuando corresponda.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Gestionar pagos de fletes, aranceles, impuestos, almacenajes y otros gastos; coordinar pagos con compras y contabilidad; dar seguimiento a liberaciones y envíos; preparar hojas de gastos; verificar la mercancía recibida y reportar discrepancias o daños.", "frecuencia": "", "tiempo": ""}], "nivel_iniciativa": "Iniciativa: Media-Alta. Debe organizar, priorizar y dar seguimiento a actividades administrativas, financieras y operativas de manera simultánea. Gestionar documentación, controlar fechas de pago y vencimiento, preparar reportes, actualizar información bancaria, coordinar trámites, dar seguimiento a proveedores y resolver incidencias operativas relacionadas con pagos, servicios e importaciones.", "toma_decisiones": "Cuenta con autonomía para comunicarse y coordinar con proveedores internacionales, navieras, agentes de carga, transportistas, agentes aduanales, SAT, bancos y áreas internas, así como para monitorear envíos, revisar documentación, identificar discrepancias y solicitar las correcciones correspondientes. No está autorizada para colocar pedidos sin autorización previa del Gerente General.", "manejo_activos": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Uniforme corporativo: camisa polo. Gafete institucional.", "equipos_seguridad": "Acceso al sistema ERP o sistema de ventas", "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico Medio, El puesto requiere permanecer sentado durante períodos prolongados para realizar actividades administrativas, financieras y documentales, así como movilizarse entre las áreas de Gerencia, Ventas, Recepción, Caja, Contabilidad y Bodega para entregar documentos, coordinar pagos, efectuar trámites y dar seguimiento a distintas gestiones. También implica el uso constante de computadora, teléfono, impresora y otros recursos de oficina. De manera eventual, puede requerir trasladarse para efectuar trámites bancarios, administrativos o relacionados con importaciones.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español/ Inglés", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado en Perito Contador, Secretaria bilingüe, Perito en Administración o carrera afín.", "formacion_complementaria": "Estudiante de Administración de Empresas, Contaduría Pública y Auditoría, Finanzas, Comercio Internacional, Administración Aduanera o carrera afín.", "conocimientos_basicos": "Control y programación de pagos; emisión y seguimiento de facturas; elaboración de estados de cuenta; manejo de cuentas bancarias; control de contratos, seguros y servicios; preparación de documentación contable; gestión de compras; trámites de vehículos; control de saldos, anticipos y pólizas de importación.", "habilidades_especificas": "Capacidad de análisis, planificación, organización, priorización, negociación, seguimiento, comunicación efectiva, resolución de problemas, manejo de información confidencial, atención al detalle y coordinación de múltiples actividades.", "conocimientos_informaticos": "Google Drive / OneDrive. WhatsApp Business. Microsoft Office: Avanzado. Otras: CRM (Zoho o similar)", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "De preferencia sí (transporte)", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, compromiso, respeto"}, "competencias_generales": [{"competencia": "Integridad y ética profesional.", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Adaptabilidad al cambio.", "grado": "B"}, {"competencia": "Trabajo en equipo.", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": ""}], "competencias_especificas": [{"competencia": "Orientación a resultados", "grado": "A"}, {"competencia": "Negociación", "grado": "A"}, {"competencia": "Cumplimiento de metas comerciales", "grado": "A"}, {"competencia": "Inteligencia emocional", "grado": "B"}, {"competencia": "Manejo de conflictos.", "grado": "A"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Financiero", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-006"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Asistente Financiero', 'Gestiona los procesos financieros y administrativos de las empresas mediante el control de pagos, cheques, registros bancarios, documentación contable, obligaciones fiscales, cajas chicas, inventarios, facturación y procesos relacionados, procurando la integridad de la información contribuyendo a la eficiencia operativa.', 'Graduado de nivel diversificado en Perito Contador, Perito en Administración o carrera afín. 2 años en puesto similar. Manejo responsable y confidencial de información financiera.', 'ACCISA-007', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Licda. Miriam de Ríos', 'Administrativo', 'Q5,600.00 Base + Bonificación', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Gestión de Pagos y Cheques", "funcion": "Emitir cheques para las cuatro empresas según requerimientos autorizados; solicitar claves y gestionar las firmas autorizadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión de Pagos y Cheques", "funcion": "Entregar cheques a proveedores y colaboradores y elaborar los reportes de cheques emitidos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Financiero y Contable", "funcion": "Registrar los débitos bancarios en el sistema y validar que las transacciones cuenten con respaldo documental, especialmente facturas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Financiero y Contable", "funcion": "Preparar la papelería contable quincenal y mensual, y controlar y archivar la documentación contable.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Fiscal (ISR e IVA) y Cumplimiento", "funcion": "Verificar las facturas con retención de ISR y generar, descargar e imprimir las retenciones correspondientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Fiscal (ISR e IVA) y Cumplimiento", "funcion": "Elaborar formularios, declaraciones juradas y reportes requeridos para los pagos fiscales.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Fiscal (ISR e IVA) y Cumplimiento", "funcion": "Realizar el control mensual de retenciones para evitar omisiones y elaborar reportes consolidados para gerencia.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Fiscal (ISR e IVA) y Cumplimiento", "funcion": "Gestionar retenciones de ISR e IVA con las entidades correspondientes, controlar retenciones a empleados y generar los pagos respectivos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control de Gastos, Cajas Chicas y Servicios", "funcion": "Archivar y controlar órdenes, vouchers y papelería contable, y coordinar el envío de documentos y garantías a bodega.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control de Gastos, Cajas Chicas y Servicios", "funcion": "Controlar insumos críticos, como cheques y talonarios, y gestionar solicitudes ante imprentas y bancos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control de Inventarios", "funcion": "Revisar y validar los inventarios de tres empresas, comparar la información del sistema con bodega y detectar inconsistencias.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación y Apoyo en Caja", "funcion": "Emitir facturas, efectuar cobros a clientes en efectivo, tarjeta o Visacuotas y entregar efectivo contra vale autorizado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación y Apoyo en Caja", "funcion": "Apoyar el control de los reportes de caja, incluyendo la revisión de facturas emitidas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Órdenes de Instalación", "funcion": "Emitir órdenes de instalación para instaladores, revisar y validar órdenes firmadas y verificar la liquidación previa a facturar.", "frecuencia": "", "tiempo": ""}, {"categoria": "Órdenes de Instalación", "funcion": "Clasificar órdenes dentro y fuera de propuesta, elaborar reportes semanales, dar seguimiento a contraseñas de facturación y coordinar órdenes pendientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Importaciones y Gerencia", "funcion": "Apoyo eventual en la gestión de procesos de importación, coordinar con navieras, proveedores y logística, contratar seguros y dar seguimiento hasta la entrega en bodega, reportando a gerencia.", "frecuencia": "Eventual", "tiempo": ""}, {"categoria": "Importaciones y Gerencia", "funcion": "Apoyo eventual a gerencia en tareas administrativas y operativas.", "frecuencia": "Eventual", "tiempo": ""}, {"categoria": "Apoyo Recepción", "funcion": "Dar seguimiento a proveedores y contraseñas de pago; atender clientes y llamadas; registrar clientes; apoyar al equipo comercial y a caja; actualizar reportes financieros y coordinar con distintas áreas.", "frecuencia": "Eventual", "tiempo": ""}], "inversion_actividades": "Complejidad alta por la combinación de pagos y cheques para cuatro empresas, controles contables y fiscales, revisión de inventarios de tres empresas, facturación, caja, documentación, importaciones y apoyo transversal. Las atribuciones requieren exactitud, seguimiento de plazos y manejo simultáneo de actividades.", "nivel_iniciativa": "Iniciativa: Media. Debe llevar el control, organización, atención al detalle, trabajo bajo presión, multitarea y adaptabilidad. No posee autoridad para autorizar pagos; las decisiones que requieran autorización deberán escalarse al Gerente Financiero.", "toma_decisiones": "Baja: Valida respaldos documentales, revisa facturas y retenciones, detecta inconsistencias, da seguimiento a pendientes y coordina gestiones con áreas internas y entidades externas.", "riesgos": "Riesgo de errores u omisiones en cheques, pagos, débitos bancarios, retenciones, declaraciones, facturación, caja, inventarios y documentación contable", "manejo_activos": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Uniforme corporativo: camisa polo. Gafete institucional.", "equipos_seguridad": "Acceso al sistema ERP o sistema de ventas. Cheques en blanco.", "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado en Perito Contador, Perito en Administración o carrera afín.", "formacion_complementaria": "Estudios en Contaduría Pública y Auditoría", "conocimientos_basicos": "Poseer lógica matemática, demostrar competencias como organización, atención al detalle para evitar errores.", "habilidades_especificas": "Manejo responsable y confidencial de información financiera", "conocimientos_informaticos": "Google Drive / OneDrive. WhatsApp Business. Microsoft Office: Avanzado. Otras: CRM (Zoho o similar)", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, responsabilidad, compromiso, respeto"}, "competencias_generales": [{"competencia": "Integridad y ética profesional.", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Adaptabilidad al cambio.", "grado": "B"}, {"competencia": "Trabajo en equipo.", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": ""}], "competencias_especificas": [{"competencia": "Orientación a resultados", "grado": "A"}, {"competencia": "Negociación", "grado": "A"}, {"competencia": "Cumplimiento de metas comerciales", "grado": "A"}, {"competencia": "Inteligencia emocional", "grado": "B"}, {"competencia": "Manejo de conflictos.", "grado": "A"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Financiero", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-007"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Mecánico Instalador', 'Ejecuta la instalación, ensamblaje y adaptación de los accesorios comercializados por Accesorios Ilimitados, utilizando correctamente las herramientas y materiales asignados, protegiendo la integridad de los vehículos y asegurando un trabajo ordenado, funcional y de calidad tanto en el centro de instalaciones como en agencias y bodegas de vehículos.', 'Graduado de nivel diversificado, preferentemente Técnico o Perito en Mecánica Automotriz, Electricidad Automotriz, Electromecánica o carrera afín. 2 años en puesto similar. Atención al detalle, habilidad manual, resolución de problemas, trabajo en equipo, orden y limpieza.', 'ACCISA-009', 'ACCISA', 'Operativa', 'Operativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Juan Luis Monzón / Bernardo Constanza', 'Operativo', 'Q4,050.00 Base + Bonificación Q250.00', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Preparación de Herramientas y Materiales", "funcion": "Preparar al inicio de la jornada los materiales, herramientas y elementos necesarios para ejecutar las instalaciones asignadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Preparación de Herramientas y Materiales", "funcion": "Revisar la disponibilidad de materiales y solicitar oportunamente los que estén próximos a agotarse para evitar interrupciones en el trabajo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Preparación de Herramientas y Materiales", "funcion": "Mantener completa y disponible la herramienta necesaria para realizar el trabajo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Revisión y Recepción del Vehículo", "funcion": "Revisar minuciosamente el vehículo antes de iniciar el trabajo e identificar y reportar cualquier desperfecto o condición preexistente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Revisión y Recepción del Vehículo", "funcion": "Informar inmediatamente al jefe inmediato cuando el vehículo no se encuentre listo para ser intervenido, para que se determine si corresponde esperar o regresar a la empresa.", "frecuencia": "", "tiempo": ""}, {"categoria": "Revisión y Recepción del Vehículo", "funcion": "Proteger y cuidar el vehículo durante todo el proceso de instalación para prevenir daños o reclamos posteriores.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Instalar los accesorios comercializados por la empresa en el centro de instalaciones, agencias establecidas y bodegas de vehículos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Armar los accesorios antes de instalarlos y realizar las modificaciones necesarias en piezas o componentes cuando el trabajo lo requiera.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Elaborar las piezas y bases necesarias para las instalaciones, incluyendo actividades de lijado y pintura cuando corresponda.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Ejecutar el armado, instalación y mantenimiento de exhibiciones, muebles y accesorios destinados a las salas de ventas, agencias y eventos comerciales, verificando que su presentación cumpla con los estándares de calidad, imagen y exhibición establecidos por la empresa.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Comunicar al jefe inmediato cuando no cuente con la capacidad técnica para realizar un trabajo, a fin de que se asigne a una persona calificada.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalaciones Externas y Desplazamientos", "funcion": "Trasladarse en el transporte designado por la empresa para realizar instalaciones en agencias ubicadas en la capital y municipios aledaños.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalaciones Externas y Desplazamientos", "funcion": "Ejecutar las instalaciones externas conforme a las indicaciones recibidas y retornar a la empresa en el transporte asignado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalaciones Externas y Desplazamientos", "funcion": "Coordinar en el lugar de trabajo las condiciones necesarias para iniciar la instalación y evitar tiempos improductivos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Documentación y Reporte", "funcion": "Velar por la correcta instalación y funcionamiento de los accesorios para prevenir reclamos y retrabajos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Documentación y Reporte", "funcion": "Llenar y firmar el informe correspondiente a los trabajos realizados fuera de la empresa, detallando lo sucedido durante la instalación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Documentación y Reporte", "funcion": "Informar oportunamente al jefe inmediato sobre incidentes, limitaciones técnicas, condiciones del vehículo o situaciones que puedan afectar la calidad y el tiempo del trabajo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Limpieza y Cuidado de Activos", "funcion": "Mantener limpia y ordenada el área de trabajo, en coordinación con los demás mecánicos instaladores.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Limpieza y Cuidado de Activos", "funcion": "Apoyar en la limpieza de las instalaciones de uso general y de los vehículos de la empresa, según la organización interna.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Limpieza y Cuidado de Activos", "funcion": "Cuidar las herramientas, materiales, accesorios y demás activos utilizados durante las instalaciones.", "frecuencia": "", "tiempo": ""}, {"categoria": "Otros", "funcion": "Realizar las demás atribuciones delegadas por el jefe inmediato que sean necesarias para el cumplimiento del puesto.", "frecuencia": "", "tiempo": ""}], "inversion_actividades": "Complejidad media-alta por la variedad de vehículos, accesorios y condiciones de instalación, así como por la necesidad de revisar previamente cada unidad, ensamblar o modificar piezas, utilizar diferentes herramientas, desplazarse a agencias y asegurar que el trabajo quede funcional y sin daños. El puesto requiere precisión técnica, cuidado de activos, cumplimiento de tiempos y capacidad para reconocer cuándo una tarea debe ser escalada.", "nivel_iniciativa": "Iniciativa: Media-Alta. Debe demostrar iniciativa para preparar sus herramientas y materiales, anticipar faltantes, inspeccionar los vehículos, identificar desperfectos, organizar el trabajo y comunicar oportunamente cualquier condición que pueda afectar la instalación.", "manejo_activos": "Vehículos de clientes y de agencias durante la intervención; accesorios, piezas, materiales, herramientas manuales y eléctricas, equipos de prueba, órdenes e informes de instalación, áreas de trabajo y vehículos de la empresa utilizados para el traslado.", "equipos_trabajo": "Uniforme corporativo, gafete institucional, caja de herramientas completa, herramientas manuales y eléctricas requeridas según el tipo de instalación, equipo básico de medición o prueba y materiales autorizados para ensamblaje, modificación, lijado y pintura.", "equipos_seguridad": "Calzado de seguridad, lentes de protección y guantes adecuados al trabajo. Protección respiratoria y auditiva cuando se realicen actividades de lijado, pintura o uso de herramientas que generen polvo o ruido. Equipamiento sujeto a la evaluación y dotación de Seguridad y Salud Ocupacional.", "condiciones_trabajo": "El puesto se desarrolla en el centro de instalaciones, talleres, agencias y bodegas de vehículos, con desplazamientos en el transporte designado por la empresa hacia la capital y municipios aledaños. Requiere permanecer de pie durante períodos prolongados, trabajar dentro y alrededor de vehículos, agacharse, arrodillarse, inclinarse y utilizar herramientas manuales o eléctricas. Puede estar expuesto a ruido, polvo, grasas, pintura y variaciones de temperatura propias del taller o de instalaciones externas. Debe mantener orden, limpieza y cuidado constante del vehículo intervenido.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico: Alto. El puesto requiere permanecer de pie durante gran parte de la jornada, adoptar posturas de agachado, arrodillado o inclinado, trabajar en espacios reducidos dentro de los vehículos, manipular herramientas, accesorios, piezas y materiales, y desplazarse a agencias o bodegas para realizar instalaciones.\nNivel de esfuerzo mental: Alto. Requiere concentración sostenida para inspeccionar el vehículo, interpretar los requerimientos de instalación, seleccionar herramientas y materiales, proteger sistemas eléctricos y componentes, identificar daños preexistentes y verificar que el accesorio funcione correctamente.", "perfil": {"edad": "18+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado, preferentemente Técnico o Perito en Mecánica Automotriz, Electricidad Automotriz, Electromecánica o carrera afín.", "formacion_complementaria": "Cursos en instalación de accesorios para vehículos, electricidad automotriz, uso seguro de herramientas, prevención de daños, Seguridad y Salud Ocupacional y manejo de extintores.", "conocimientos_basicos": "Mecánica y electricidad automotriz básica; instalación y conexión de accesorios.", "habilidades_especificas": "Atención al detalle, habilidad manual, resolución de problemas, comunicación efectiva, trabajo en equipo, orden y limpieza, adaptación a distintos vehículos, orientación a la calidad y cuidado de bienes del cliente.", "conocimientos_informaticos": "Manejo básico de teléfono inteligente, mensajería y herramientas de registro digital cuando sean utilizadas para coordinar o documentar instalaciones.", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Responsabilidad, integridad, compromiso, respeto, puntualidad, orden y cuidado de los vehículos.", "otros": "Disponibilidad para trabajar en instalaciones externas y para utilizar el equipo de protección personal requerido según la tarea."}, "competencias_generales": [{"competencia": "Responsabilidad", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Orden y limpieza", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}], "competencias_especificas": [{"competencia": "Instalación de accesorios", "grado": "A"}, {"competencia": "Inspección y cuidado del vehículo", "grado": "A"}, {"competencia": "Control de calidad", "grado": "A"}, {"competencia": "Electricidad y mecánica automotriz", "grado": "A"}, {"competencia": "Uso seguro de herramientas", "grado": "B"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Supervisor de Taller", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. Ref. ACCISA-009"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Supervisor de Taller', 'Dirige y supervisa las operaciones del taller de instalaciones, organizando el inicio y la distribución de los trabajos, controlando al personal, los tiempos, los inventarios, las herramientas, la maquinaria, los gastos y la caja chica, y verificando la calidad de los trabajos ejecutados, para asegurar entregas oportunas, un ambiente de trabajo ordenado y la reducción de reclamos de los clientes.', 'Graduado de nivel diversificado como Técnico o Perito en Mecánica Automotriz, Electricidad Automotriz, Electromecánica o carrera afín. 2 años en puesto similar. Liderazgo, planificación, organización, comunicación efectiva, manejo de conflictos.', 'ACCISA-010', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Allan Hernández', 'Administrativo/Operativo', 'Q Base + Bonificación', $json${"no_supervisa": "11", "posiciones_supervisa": "Mecánicos Instaladores", "funciones": [{"categoria": "Planeación y Asignación del Trabajo", "funcion": "Ordenar el inicio de las labores del taller y establecer la forma de proceder para los trabajos correspondientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Planeación y Asignación del Trabajo", "funcion": "Definir la secuencia y programación de los trabajos considerando las prioridades, fechas de entrega, carga de trabajo y capacidad técnica del personal.", "frecuencia": "", "tiempo": ""}, {"categoria": "Planeación y Asignación del Trabajo", "funcion": "Asignar los trabajos de manera equitativa y organizar los tiempos de descanso pactados por la empresa.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión del Personal y Desempeño", "funcion": "Supervisar el trabajo del personal del taller y verificar el cumplimiento de las actividades asignadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión del Personal y Desempeño", "funcion": "Controlar la asistencia, las horas extraordinarias y demás conceptos relacionados con el tiempo laborado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión del Personal y Desempeño", "funcion": "Mantener el archivo del personal a su cargo y registrar rendimiento, ausencias e irregularidades de comportamiento.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión del Personal y Desempeño", "funcion": "Promover la cordialidad, la cooperación y el trato respetuoso dentro del equipo, y brindar retroalimentación ante deficiencias de desempeño.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Entregas y Servicio", "funcion": "Velar por la calidad del trabajo realizado por el personal del taller para minimizar reclamos de clientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Entregas y Servicio", "funcion": "Inspeccionar los trabajos terminados y verificar su funcionamiento y conformidad antes de autorizar la entrega.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Entregas y Servicio", "funcion": "Ajustar la operación a las fechas y horarios requeridos para la calendarización y entrega de trabajos terminados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Inventarios, Equipos y Condiciones del Taller", "funcion": "Identificar necesidades de materiales, herramientas, equipos o repuestos y gestionar oportunamente su requerimiento con el área correspondiente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Inventarios, Equipos y Condiciones del Taller", "funcion": "Controlar los inventarios de herramientas y equipos asignados al taller y a cada trabajador.", "frecuencia": "", "tiempo": ""}, {"categoria": "Inventarios, Equipos y Condiciones del Taller", "funcion": "Revisar el estado de las herramientas, equipos y áreas de trabajo y coordinar las acciones de mantenimiento o corrección necesarias.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Administrativo, Gastos y Reportes", "funcion": "Informar al Supervisor de Ventas y Taller cualquier anomalía, novedad o situación relevante dentro del área a su cargo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Administrativo, Gastos y Reportes", "funcion": "Controlar los gastos ejecutados en el taller y administrar la caja chica para cubrir gastos del giro diario autorizados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Administrativo, Gastos y Reportes", "funcion": "Llevar el control de caja chica y presentar la documentación y los reportes correspondientes al Gerente Administrativo para revisión y aprobación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Seguridad, Capacitación y Mejora", "funcion": "Vigilar las condiciones de seguridad del taller, el uso adecuado de herramientas y equipos y el cumplimiento de los procedimientos aplicables.", "frecuencia": "", "tiempo": ""}, {"categoria": "Seguridad, Capacitación y Mejora", "funcion": "Coordinar o brindar inducción y capacitación sobre procedimientos de instalación, uso de equipos, calidad y prácticas seguras, y reportar los incidentes ocurridos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Seguridad, Capacitación y Mejora", "funcion": "Proponer mejoras en la organización del trabajo, calidad, productividad, uso de recursos y prevención de reclamos, y cumplir las demás atribuciones delegadas por el jefe inmediato.", "frecuencia": "", "tiempo": ""}, {"categoria": "Otros", "funcion": "Brindar apoyo operativo al equipo técnico cuando la carga de trabajo o las necesidades del servicio lo requieran, participando directamente en la instalación de accesorios, reparaciones o trabajos pendientes.", "frecuencia": "", "tiempo": ""}], "inversion_actividades": "Complejidad: Alta. El puesto combina la planificación diaria del taller, asignación de trabajos, supervisión del personal, control de asistencia y horas extraordinarias, cumplimiento de fechas de entrega, verificación de calidad, control de inventarios, herramientas, maquinaria, gastos y caja chica.", "nivel_iniciativa": "Iniciativa: Media-Alta. Cuenta con autonomía operativa para asignar tareas, ordenar la secuencia del trabajo, coordinar descansos, verificar la calidad y detener actividades que presenten riesgos o incumplimientos. Los gastos no previstos, sanciones laborales, compras relevantes y decisiones que comprometan recursos o condiciones de entrega deben escalarse al Gerente Administrativo.", "manejo_activos": "Inventario del taller; herramientas, equipos y maquinaria asignados al área y a cada trabajador; caja chica y documentación de gastos; registros de asistencia, horas extraordinarias, desempeño y novedades del personal; órdenes de trabajo, programación de entregas y vehículos o accesorios bajo responsabilidad del taller durante la instalación.", "equipos_trabajo": "Uniforme corporativo y gafete; computadora; impresora; formatos o sistema para órdenes de trabajo, inventarios y reportes; herramientas de inspección y medición; acceso a maquinaria y equipos del taller según autorización.", "equipos_seguridad": "Calzado de seguridad, lentes de protección y guantes adecuados al trabajo. Protección respiratoria y auditiva cuando se realicen actividades de lijado, pintura o uso de herramientas que generen polvo o ruido.", "condiciones_trabajo": "El puesto se desarrolla principalmente en el taller de instalaciones, combinando actividades de supervisión en piso con tareas administrativas y de control. Requiere movilizarse constantemente entre las áreas de trabajo, revisar instalaciones, herramientas, equipos e inventarios, atender al personal y coordinar con Gerencia, Ventas y Bodega.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico: Medio-Alto. El puesto requiere alternar períodos de trabajo administrativo con recorridos frecuentes por el taller, permanecer de pie, inspeccionar trabajos dentro y alrededor de vehículos, revisar herramientas, equipos e inventarios y, cuando sea necesario, apoyar o demostrar procedimientos técnicos.\nNivel de esfuerzo mental: Alto. Requiere concentración, criterio técnico y capacidad para coordinar simultáneamente personal, trabajos, fechas de entrega, calidad, inventarios, gastos, caja chica y novedades laborales.", "perfil": {"edad": "35+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado como Técnico o Perito en Mecánica Automotriz, Electricidad Automotriz, Electromecánica o carrera afín. Estudios universitarios en administración, ingeniería o gestión de operaciones son deseables, no indispensables.", "formacion_complementaria": "Cursos o diplomados en supervisión y liderazgo, planificación de talleres, control de calidad, manejo de inventarios, administración de caja chica, Excel y gestión de indicadores.", "conocimientos_basicos": "Mecánica y electricidad automotriz básica; instalación y conexión de accesorios.", "habilidades_especificas": "Liderazgo, planificación, organización, asignación equitativa del trabajo, comunicación efectiva, manejo de conflictos, retroalimentación, resolución de problemas, atención al detalle, orientación a resultados, trabajo bajo presión y servicio al cliente interno y externo.", "conocimientos_informaticos": "Microsoft Excel intermedio, Word, correo corporativo, Google Drive u OneDrive y herramientas digitales para reportes, asistencia, programación e inventarios.", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente, según las necesidades de supervisión de instalaciones externas.", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, responsabilidad, respeto, imparcialidad, compromiso, disciplina, orden, prudencia y orientación a la calidad.", "otros": "Disponibilidad para adaptar horarios a la programación de entregas terminadas y atender situaciones operativas extraordinarias."}, "competencias_generales": [{"competencia": "Responsabilidad", "grado": "A"}, {"competencia": "Planificación y organización", "grado": "A"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Liderazgo", "grado": "A"}, {"competencia": "Toma de decisiones", "grado": "B"}], "competencias_especificas": [{"competencia": "Instalación de accesorios", "grado": "A"}, {"competencia": "Inspección y cuidado del vehículo", "grado": "A"}, {"competencia": "Control de calidad", "grado": "A"}, {"competencia": "Gestión de personal", "grado": "A"}, {"competencia": "Uso seguro de herramientas", "grado": "B"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Supervisor de Taller", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-010"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Encargado de Bodega', 'Administra y controla la mercadería asignada a la bodega del taller, asegurando su correcta recepción, clasificación, almacenamiento, registro y despacho contra la documentación autorizada, así como el orden de las existencias en bodega, sala de ventas y puntos de exhibición, para mantener información confiable y disponibilidad oportuna de los productos requeridos por Taller y Ventas.', 'Graduado de nivel diversificado como Perito Contador, Perito en Administración, Bachiller en Computación o carrera afín. 2 años en puesto similar. Organización, atención al detalle, habilidad numérica, integridad.', 'ACCISA-010', 'ACCISA', 'Operativo', 'Operativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Allan Hernández', 'Operativo', 'Q Base + Bonificación', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Recepción y Validación de Mercadería", "funcion": "Recibir la mercadería destinada a la bodega y comprobar que cuente con la documentación correspondiente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Recepción y Validación de Mercadería", "funcion": "Verificar la cantidad y condición de la mercadería recibida contra facturas, órdenes, traslados u otros documentos disponibles, y reportar diferencias o daños.", "frecuencia": "", "tiempo": ""}, {"categoria": "Recepción y Validación de Mercadería", "funcion": "Registrar documentalmente el ingreso de la mercadería y ubicarla en el espacio asignado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Despacho y Entrega Controlada", "funcion": "Entregar la mercadería solicitada por Taller o Ventas únicamente contra una orden de despacho o una factura debidamente pagada.", "frecuencia": "", "tiempo": ""}, {"categoria": "Despacho y Entrega Controlada", "funcion": "Despachar los productos requeridos cumpliendo las normas y controles establecidos para la salida de mercadería.", "frecuencia": "", "tiempo": ""}, {"categoria": "Despacho y Entrega Controlada", "funcion": "Registrar documentalmente cada egreso de mercadería y conservar el respaldo correspondiente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Despacho y Entrega Controlada", "funcion": "Verificar que el producto, cantidad y documento de entrega coincidan antes de completar el despacho.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Documental e Inventarios", "funcion": "Mantener un expediente y control estricto de todas las existencias, ingresos y egresos de mercadería.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Documental e Inventarios", "funcion": "Realizar arqueos selectivos o aleatorios de la mercadería en las bodegas centrales cuando lo considere oportuno.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Documental e Inventarios", "funcion": "Investigar y reportar las diferencias detectadas entre las existencias físicas y los registros, sin efectuar ajustes no autorizados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Clasificación y Exhibición", "funcion": "Ordenar y colocar la mercadería de forma clasificada dentro de la bodega y en la sala de ventas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Clasificación y Exhibición", "funcion": "Mantener el orden y la limpieza de las áreas de bodega.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Clasificación y Exhibición", "funcion": "Controlar las mercaderías en exhibición en los puntos de venta establecidos mediante convenios especiales.", "frecuencia": "", "tiempo": ""}, {"categoria": "Saldos, Abastecimiento y Rotación", "funcion": "Informar al Gerente de Ventas y al Gerente Financiero los saldos, requerimientos y necesidades de importación de los productos a su cargo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Saldos, Abastecimiento y Rotación", "funcion": "Informar al Gerente de Ventas sobre la rotación de los productos para apoyar la definición de políticas de venta.", "frecuencia": "", "tiempo": ""}, {"categoria": "Saldos, Abastecimiento y Rotación", "funcion": "Cumplir las demás atribuciones delegadas por el jefe inmediato que sean necesarias para el cumplimiento del puesto.", "frecuencia": "", "tiempo": ""}], "inversion_actividades": "Complejidad: Media-Alta. El puesto combina la recepción y entrega de mercadería, el control documental de ingresos y egresos, la clasificación física de productos, la realización de arqueos selectivos, la vigilancia de existencias en bodega y exhibiciones, y el reporte de saldos, rotación, faltantes y requerimientos de importación.", "nivel_iniciativa": "Iniciativa: Media-Alta. Cuenta con autonomía operativa para ordenar la bodega, verificar la documentación y ejecutar despachos debidamente autorizados.", "manejo_activos": "Mercadería almacenada en la bodega del taller y bodega central; productos ubicados en sala de ventas y puntos de exhibición por convenios especiales; documentos de ingreso y egreso, órdenes de despacho, facturas pagadas, expedientes de existencias, reportes de saldos, rotación, faltantes y requerimientos de importación.", "equipos_trabajo": "Uniforme corporativo y gafete; computadora, impresora, calculadora, formatos de control o acceso al sistema.", "equipos_seguridad": "Calzado de seguridad y guantes adecuados para la manipulación de mercadería; chaleco reflectivo cuando exista circulación de vehículos o equipos de manejo de materiales.", "condiciones_trabajo": "El puesto se desarrolla principalmente en bodegas, áreas de almacenamiento, sala de ventas y puntos de exhibición asignados. Combina trabajo documental y uso de sistemas con recorridos frecuentes, recepción, clasificación, conteo y entrega de mercadería.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico: Alto. El puesto requiere permanecer de pie durante parte importante de la jornada, caminar dentro de las áreas de bodega, agacharse, inclinarse, alcanzar estanterías y manipular, ordenar o trasladar mercadería.\nNivel de esfuerzo mental: Alto. Requiere concentración y atención al detalle para comparar documentos, verificar cantidades, registrar movimientos, mantener el control de las existencias, realizar conteos, identificar diferencias y reportar saldos, rotación, faltantes y requerimientos sin afectar la continuidad del Taller y Ventas.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado como Perito Contador, Perito en Administración, Bachiller en Computación o carrera afín.", "formacion_complementaria": "Cursos en manejo de inventarios, recepción y despacho, Excel, seguridad en bodegas, manipulación manual de materiales, orden y limpieza o metodología 5S.", "conocimientos_basicos": "Recepción y despacho de mercadería; revisión de órdenes, facturas y traslados; control de ingresos y egresos.", "habilidades_especificas": "Organización, atención al detalle, habilidad numérica, seguimiento, comunicación efectiva, integridad, orientación al servicio interno, capacidad para identificar diferencias, orden, disciplina y cuidado de la mercadería.", "conocimientos_informaticos": "Microsoft Excel intermedio, Word y herramientas digitales para reportes, programación e inventarios.", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente, según las necesidades de supervisión de instalaciones externas.", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, responsabilidad, respeto, imparcialidad, compromiso, disciplina, orden, prudencia y orientación a la calidad.", "otros": "Disponibilidad para realizar conteos, cierres o verificaciones extraordinarias cuando sean programadas y autorizadas."}, "competencias_generales": [{"competencia": "Organización y control", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Responsabilidad", "grado": "A"}], "competencias_especificas": [{"competencia": "Gestión de inventarios", "grado": "A"}, {"competencia": "Recepción y despacho", "grado": "A"}, {"competencia": "Conteos y arqueos", "grado": "A"}, {"competencia": "Análisis de rotación y faltantes", "grado": "B"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Supervisor de Taller", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-010 (Bodega)"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Mensajero', 'Ejecuta de forma segura y confidencial las gestiones de mensajería asignadas por Grupo IMISA, trasladando documentos, valores, paquetes, compras y otros requerimientos autorizados, realizando trámites bancarios y administrativos, utilizando la motocicleta o vehículo de la empresa, para apoyar la continuidad de las operaciones.', 'Graduado de nivel diversificado como Bachiller en Computación o carrera afín. 2 años en puesto similar. Licencia de conducir vigente. Proactividad, discreción, responsabilidad, puntualidad.', 'ACCISA-012', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'María José Hernández', 'Operativo', 'Q Base + Bonificación', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Planificación, Priorización y Control de Ruta", "funcion": "Atender las solicitudes de mensajería asignadas por las distintas áreas y organizar la ruta de acuerdo con los destinos y prioridades informadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Planificación, Priorización y Control de Ruta", "funcion": "Dar prioridad a las gestiones de emergencia o alta prioridad cuando se presenten, sin limitarse únicamente al orden inicialmente programado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Planificación, Priorización y Control de Ruta", "funcion": "Mantener informado a su jefe inmediato para tener actualizado el reporte de ruta con información de destino, gestión, prioridad, horas de salida/retorno y estado de la diligencia.", "frecuencia": "", "tiempo": ""}, {"categoria": "Traslado de Documentos, Valores y Paquetes", "funcion": "Transportar documentos importantes, valores de la empresa y de los gerentes con diligencia, discreción y resguardo durante todo el recorrido.", "frecuencia": "", "tiempo": ""}, {"categoria": "Traslado de Documentos, Valores y Paquetes", "funcion": "Entregar y recoger sobres, facturas, contraseñas, retenciones, boletas, documentos, muestras y demás papelería solicitada en las rutas asignadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Traslado de Documentos, Valores y Paquetes", "funcion": "Trasladar paquetes grandes, medianos y pequeños, verificando su entrega en el destino indicado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Traslado de Documentos, Valores y Paquetes", "funcion": "Trasladar paquetes o compras utilizando el automóvil de la empresa cuando sea una emergencia y/o cuando el piloto no se encuentre presente, previamente autorizado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Trámites Bancarios, Pagos y Cobros", "funcion": "Realizar trámites bancarios autorizados, incluyendo depósitos y cambios de cheques.", "frecuencia": "", "tiempo": ""}, {"categoria": "Trámites Bancarios, Pagos y Cobros", "funcion": "Efectuar pagos de servicios, depósitos y otras diligencias financieras incluidas en la ruta, conforme a la documentación e instrucciones recibidas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Compras, Recolecciones y Apoyo Interdepartamental", "funcion": "Realizar compras y recoger materiales, suministros, accesorios u otros artículos solicitados y autorizados por las áreas correspondientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Compras, Recolecciones y Apoyo Interdepartamental", "funcion": "Apoyar a otros departamentos en diligencias externas cuando sea solicitado, conforme a las prioridades de la operación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Compras, Recolecciones y Apoyo Interdepartamental", "funcion": "Realizar trámites administrativos externos autorizados ante empresas, instituciones y otros puntos incluidos en la ruta.", "frecuencia": "", "tiempo": ""}, {"categoria": "Servicio, Conducta y Confidencialidad", "funcion": "Mantener una actitud proactiva, informar oportunamente cualquier incidencia en la ruta y cumplir las demás atribuciones delegadas por el jefe inmediato relacionadas con el puesto.", "frecuencia": "", "tiempo": ""}], "inversion_actividades": "Complejidad: Media-Alta. El puesto combina desplazamientos continuos, manejo de rutas con prioridades cambiantes, trámites bancarios, cobros, compras, entregas y recolecciones de documentos, valores y paquetes.", "nivel_iniciativa": "Iniciativa: Baja. Debe demostrar proactividad para organizar sus recorridos, atender prioridades y emergencias, dar seguimiento a las diligencias, informar retrasos o incidencias y mantener actualizado el reporte de ruta.", "manejo_activos": "Automóvil de la empresa cuando sea autorizado; documentos importantes, valores, cheques, depósitos, sobres, facturas, contraseñas, retenciones, paquetes, compras y materiales transportados; GPS y reporte de ruta.", "equipos_trabajo": "Uniforme corporativo y gafete, si forman parte de la dotación institucional; teléfono y acceso al formato digital de reporte de ruta.", "condiciones_trabajo": "El puesto se desarrolla mayoritariamente fuera de las instalaciones de la empresa, realizando recorridos en motocicleta y, cuando se requiera, en automóvil de la empresa. Implica desplazamiento frecuente por distintas zonas de la Ciudad de Guatemala y puntos aledaños, visitas a bancos, clientes, proveedores, agencias, comercios e instituciones.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico: Medio-Alto. El puesto requiere conducir motocicleta durante buena parte de la jornada, caminar entre destinos y trasladar documentos, compras y paquetes de tamaños diversos.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado como Bachiller en Computación o carrera afín.", "formacion_complementaria": "No indispensable", "conocimientos_basicos": "Conocimiento de rutas y ubicaciones de la ciudad, cambios de cheques, pagos, cobros y entrega de documentos; control de paquetes y valores; lectura y seguimiento de prioridades.", "habilidades_especificas": "Proactividad, discreción, responsabilidad, puntualidad, orientación al servicio, organización, sentido de urgencia, atención al detalle, comunicación efectiva, manejo de prioridades y capacidad para trabajar de forma autónoma en ruta.", "conocimientos_informaticos": "No indispensable", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Sí. Desplazamientos frecuentes dentro de Ciudad de Guatemala y puntos aledaños conforme a la ruta asignada.", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Honestidad, integridad, discreción, responsabilidad, respeto, prudencia, compromiso y orientación al servicio.", "otros": "Licencia de conducir vigente que habilite legalmente la conducción de los vehículos que la empresa le asigne."}, "competencias_generales": [{"competencia": "Organización y control", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Responsabilidad", "grado": "A"}], "competencias_especificas": [{"competencia": "Gestión de inventarios", "grado": "A"}, {"competencia": "Recepción y despacho", "grado": "A"}, {"competencia": "Conteos y arqueos", "grado": "A"}, {"competencia": "Análisis de rotación y faltantes", "grado": "B"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente de Operaciones", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-012"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Cajera', 'Administra y controla las operaciones de caja, cobros, facturación, registros bancarios y fondos asignados, verificando que cada transacción cuente con su respaldo y registro correspondiente, para contribuir al control financiero y operativo de Accesorios Ilimitados.', 'Graduado de nivel diversificado en Perito Contador, Perito en Administración o carrera afín. 2 años en puesto similar. Atención al detalle, capacidad de cuadre, organización documental.', 'ACCISA-008', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Licda. Miriam de Ríos', 'Administrativo', 'Q5,050.00 Base + Bonificación', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Cobros y Atención en Caja", "funcion": "Realizar cobros a clientes de sala, recibir efectivo, verificar billetes y procesar cobros con tarjeta.", "frecuencia": "", "tiempo": ""}, {"categoria": "Cobros y Atención en Caja", "funcion": "Emitir un recibo de caja por cada factura correspondiente a las ventas diarias.", "frecuencia": "", "tiempo": ""}, {"categoria": "Reportes y Control Diario de Ventas", "funcion": "Elaborar los reportes de ventas diarias, adjuntando la copia amarilla del recibo de caja y el comprobante de pago.", "frecuencia": "", "tiempo": ""}, {"categoria": "Reportes y Control Diario de Ventas", "funcion": "Adjuntar traslados y pagos de impuestos, registrar los recibos de caja en la hoja de ingresos y egresos e ingresar créditos y débitos al reporte de cuentas bancarias.", "frecuencia": "", "tiempo": ""}, {"categoria": "Reportes y Control Diario de Ventas", "funcion": "Imprimir el reporte de corte diario de ventas del sistema y enviar los reportes mensuales a Contabilidad.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Bancario y Conciliaciones", "funcion": "Actualizar el libro de bancos registrando créditos y débitos en cada cuenta bancaria.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Bancario y Conciliaciones", "funcion": "Realizar conciliaciones bancarias de G&T en quetzales, Banrural, G&T en dólares, BAC, BAM e Industrial.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Bancario y Conciliaciones", "funcion": "Enviar transacciones bancarias, incluyendo depósitos, pagos y otras operaciones, y confirmar depósitos o transferencias bancarias en Banco Industrial.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Bancario y Conciliaciones", "funcion": "Llenar boletas de depósito relacionadas con pagos recibidos por depósito o transferencia.", "frecuencia": "", "tiempo": ""}, {"categoria": "Cobros a Crédito y Facturación", "funcion": "Emitir recibos de caja por cobros a crédito y cuadrar los pagos con las contraseñas, aplicando retenciones, anticipos o abonos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Cobros a Crédito y Facturación", "funcion": "Ingresar los recibos de cobros a crédito al sistema, generar facturas de crédito y enviarlas por correo a los vendedores.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control y Ajustes en el Sistema", "funcion": "Apoyar la anulación de facturas en el sistema.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control y Ajustes en el Sistema", "funcion": "Realizar cambios en órdenes de instalación cuando exista información incorrecta o faltante.", "frecuencia": "", "tiempo": ""}, {"categoria": "Caja Chica, Efectivo y Pagos", "funcion": "Controlar las contraseñas de pago y realizar seguimiento semanal y al cierre de mes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Caja Chica, Efectivo y Pagos", "funcion": "Administrar la caja chica: entregar efectivo contra vales, elaborar el reporte de facturas para solicitar reintegro y cuadrar el dinero para depósito o entrega.", "frecuencia": "", "tiempo": ""}, {"categoria": "Caja Chica, Efectivo y Pagos", "funcion": "Llevar el control del efectivo destinado a pagos en coordinación con la Licda. Miriam.", "frecuencia": "", "tiempo": ""}, {"categoria": "Entrega y Control de Valores", "funcion": "Entregar bonificaciones a instaladores y llevar el control relacionado con el pago del plan Tigo empresarial de quienes cuentan con línea.", "frecuencia": "", "tiempo": ""}, {"categoria": "Entrega y Control de Valores", "funcion": "Entregar cheques a proveedores, elaborar el listado para recepción, solicitar la contraseña de pago y verificar la emisión del recibo de caja.", "frecuencia": "Semanal", "tiempo": ""}, {"categoria": "Entrega y Control de Valores", "funcion": "Controlar los vales de combustible, tomando fotografía y entregando el vale a la persona solicitante para mantener el registro.", "frecuencia": "Eventual", "tiempo": ""}], "inversion_actividades": "Complejidad: Alta. El puesto combina atención directa a clientes, manejo de efectivo y cobros con tarjeta, emisión de recibos y facturas, elaboración de cortes y reportes diarios, control de cuentas bancarias, conciliaciones, seguimiento de cobros a crédito, administración de caja chica, entrega de cheques y control de otros valores.", "nivel_iniciativa": "Iniciativa: Media. Puede organizar y ejecutar las actividades rutinarias de caja con autonomía operativa; sin embargo, las anulaciones de facturas, reintegros, entregas extraordinarias de efectivo y demás operaciones que requieran autorización deben ser consultadas con la jefatura correspondiente.", "toma_decisiones": "Nivel: Medio. Puede tomar decisiones operativas relacionadas con la validación de pagos, aplicación de retenciones, anticipos o abonos, confirmación de depósitos, preparación de boletas, registro de movimientos y organización de los respaldos documentales. No posee autoridad para aprobar pagos, disponer de fondos sin respaldo, modificar condiciones de crédito o efectuar anulaciones sin la autorización correspondiente.", "manejo_activos": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Uniforme corporativo: camisa polo. Gafete institucional.", "equipos_seguridad": "Acceso al sistema ERP o sistema de cobros. Caja Chica QXXXX.", "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico: Bajo-Medio. El puesto requiere permanecer sentado y de pie de forma alterna, atender clientes en caja, movilizarse dentro de las instalaciones para entregar cheques, documentos, vales o reportes y utilizar de manera constante equipo de cómputo y terminales de cobro.\nNivel de esfuerzo mental: Alto. Requiere mantener concentración constante para recibir y verificar efectivo, procesar pagos con tarjeta, emitir recibos y facturas, aplicar retenciones, anticipos o abonos, realizar cortes diarios, conciliar cuentas bancarias y controlar caja chica, cheques y vales.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado en Perito Contador, Perito en Administración o carrera afín.", "formacion_complementaria": "Estudios en Contaduría Pública y Auditoría", "conocimientos_basicos": "Cobros en efectivo y tarjeta; emisión de recibos y facturas; conciliaciones bancarias; depósitos y transferencias; cuentas por cobrar; caja chica; control de cheques y contraseñas.", "habilidades_especificas": "Atención al detalle, capacidad de cuadre, organización documental, atención al cliente, comunicación efectiva, manejo de conflictos, seguimiento, concentración y trabajo bajo presión.", "conocimientos_informaticos": "Google Drive / OneDrive. WhatsApp Business. Microsoft Office: Avanzado. Otras: CRM (Zoho o similar)", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, honradez, compromiso, respeto"}, "competencias_generales": [{"competencia": "Integridad y ética profesional.", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Adaptabilidad al cambio.", "grado": "B"}, {"competencia": "Trabajo en equipo.", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": "A"}], "competencias_especificas": [{"competencia": "Orientación a resultados", "grado": "A"}, {"competencia": "Negociación", "grado": "A"}, {"competencia": "Cumplimiento de metas comerciales", "grado": "A"}, {"competencia": "Inteligencia emocional", "grado": "B"}, {"competencia": "Manejo de conflictos.", "grado": "A"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Financiero", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-008"}$json$::jsonb)
